class Solution {
    private int digitSum(int value){
        int sum=0;
        while(value>0){
            sum+=value%10;
            value/=10;
        }
        return sum;
    }
    public int countBalls(int lowLimit,int highLimit){
        int[] counts=new int[50];
        int answer=0;
        for(int value=lowLimit;value<=highLimit;value++)answer=Math.max(answer,++counts[digitSum(value)]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countBalls(lowLimit:Int,highLimit:Int):Int{
        val counts=IntArray(50);
        var answer=0;
        for(original in lowLimit..highLimit){
            var value=original;
            var sum=0;
            while(value>0){
                sum+=value%10;
                value/=10
            };
            counts[sum]++;
            answer=maxOf(answer,counts[sum])
        };
        return answer
    }
}

